import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  await readFile(path.join(root, "contracts/workforce-staff-actors.json"), "utf8"),
);
const output = emitModels(contract.models);
await writeGenerated(
  root,
  "backend/internal/modules/workforce/staff_actor_types_generated.go",
  '// Code generated by scripts/generate-workforce-staff-actors.mjs; DO NOT EDIT.\npackage workforce\nimport "github.com/google/uuid"\n' +
    output.go,
  "packages/api/src/staff-actor-contract.ts",
  '// Generated by scripts/generate-workforce-staff-actors.mjs.\nimport {z} from "zod";\n' +
    output.ts,
  "Workforce Staff actor metadata",
);
